    fun generateAllTriviaLevels(): List<EntertainmentPuzzleEntity> {
        val now = System.currentTimeMillis()
        val result = mutableListOf<EntertainmentPuzzleEntity>()
        val packs = listOf(
            EntertainmentDifficulty.BEGINNER to TRIVIA_BEGINNER,
            EntertainmentDifficulty.INTERMEDIATE to TRIVIA_INTERMEDIATE,
            EntertainmentDifficulty.ADVANCED to TRIVIA_ADVANCED,
            EntertainmentDifficulty.MASTER to TRIVIA_MASTER
        )
        for ((diff, list) in packs) {
            list.forEachIndexed { idx, item ->
                val level = idx + 1
                result.add(
                    EntertainmentPuzzleEntity(
                        id = "trivia_${diff.key.lowercase()}_$level",
                        gameType = EntertainmentGameType.TRIVIA.key,
                        difficulty = diff.key,
                        levelNumber = level,
                        title = "معمای ${diff.titleFa} - مرحله $level",
                        payloadJson = serializeTrivia(item),
                        updatedAtEpochMs = now
                    )
                )
            }
        }
        return result
    }

    fun serializeTrivia(data: TriviaQuestionData): String {
        val opts = JSONArray()
        data.options.forEach { opts.put(it) }
        return JSONObject().apply {
            put("question", data.question)
            put("options", opts)
            put("correctIndex", data.correctIndex)
            put("category", data.category)
            put("explanation", data.explanation)
        }.toString()
    }

    fun deserializeTrivia(json: String): TriviaQuestionData? {
        return try {
            val obj = JSONObject(json)
            val arr = obj.getJSONArray("options")
            val opts = List(arr.length()) { arr.getString(it) }
            TriviaQuestionData(
                question = obj.getString("question"),
                options = opts,
                correctIndex = obj.getInt("correctIndex"),
                category = obj.optString("category", "اطلاعات عمومی"),
                explanation = obj.optString("explanation", "")
            )
        } catch (_: Exception) {
            null
        }
    }
}
